mapper.select:
select , memo_content from sys_memo
where memo_id = #{memoId}

    and (visibility = '1' or owner_user_id = #{userId})

mapper.update:
update sys_memo
set title = #{memo.title}, resource_url = #{memo.resourceUrl}, memo_content = #{memo.contentCipher},
    remark = #{memo.remark}, visibility = #{memo.visibility},
    update_by = #{memo.updateBy}, update_time = sysdate(), version = version + 1
where memo_id = #{memo.memoId} and version = #{memo.version}

    and owner_user_id = #{userId}

mapper.delete:
delete from sys_memo
where memo_id = #{memoId} and version = #{version}

    and owner_user_id = #{userId}
